#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-10-15

# Test: the "Open PR with the new row" step of
# .github/workflows/traffic-snapshot.yml refreshes the PR body when this
# week's PR already exists (#4752).
#
# Why: on a re-dispatch the branch is force-pushed with the new row, but
# `gh pr create` fails because the PR is already open. The else branch used to
# only warn, so the PR kept the OLD body while the branch carried the NEW row:
# the numbers on the PR no longer matched the ledger. The step must write the
# freshly built body to the open PR (`gh pr edit <branch> --body-file`), and
# only warn when that edit also fails.
#
# Behavioral, not a grep of the fix: the PR-body-and-create portion of the
# step's `run:` script is extracted from the YAML and executed with bash
# against a stubbed `gh` that logs every call. The extraction is bounded by two
# markers; if either goes missing the test FAILS rather than running nothing.
#
# Arms (WEEK=2026-09-07, fixture ledger of two rows with different numbers, so
# the body must come from the LAST row):
#   fault:   gh pr create fails ("already exists")
#            -> exactly one `gh pr edit traffic/snapshot-2026-09-07
#               --body-file <path>`; the body that edit received carries the
#               last row's numbers and not the first row's; exit 0; no warning
#   control: gh pr create succeeds
#            -> no `gh pr edit` call; "opened PR for <branch>" printed
#   both:    gh pr create fails AND gh pr edit fails
#            -> exit 0 (never aborts), a ::warning:: line on stdout

set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
WORKFLOW="$REPO_ROOT/.github/workflows/traffic-snapshot.yml"

echo "=== traffic-snapshot PR body refresh gate (#4752) ==="
echo ""

WORK="$(mktemp -d "${TMPDIR:-/tmp}/ork-traffic-pr-body.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT

PASS=0
FAIL=0
ok()  { echo "  PASS: $1"; PASS=$((PASS + 1)); }
bad() { echo "  FAIL: $1"; FAIL=$((FAIL + 1)); }

START_MARKER='# PR body from the row itself'
# shellcheck disable=SC2016  # literal workflow text, must not expand
END_MARKER='rm -f "$BODY_FILE"'
WEEK_VALUE="2026-09-07"
BRANCH_VALUE="traffic/snapshot-${WEEK_VALUE}"

# --- extract the snippet from the workflow -----------------------------------
SNIPPET="$WORK/snippet.sh"
if [ ! -f "$WORKFLOW" ]; then
  echo "  FAIL: workflow not found: $WORKFLOW"
  exit 1
fi
START_COUNT="$(awk -v m="$START_MARKER" 'index($0, m) { n++ } END { print n + 0 }' "$WORKFLOW")"
if [ "$START_COUNT" -ne 1 ]; then
  echo "  FAIL: start marker '$START_MARKER' found $START_COUNT time(s) in $WORKFLOW, expected exactly 1; the extraction would be wrong or vacuous, update this test with the refactor"
  exit 1
fi
# The run block is indented 10 spaces; strip them. Stop at the first
# `rm -f "$BODY_FILE"` line at or after the start marker (inclusive).
awk -v start="$START_MARKER" -v stop="$END_MARKER" '
  !on && index($0, start) { on = 1 }
  on {
    line = $0
    sub(/^ {10}/, "", line)
    print line
    t = line
    sub(/^[ \t]+/, "", t)
    if (t == stop) { done = 1; exit }
  }
  END { if (!done) exit 3 }
' "$WORKFLOW" > "$SNIPPET" || {
  echo "  FAIL: end marker '$END_MARKER' not found after '$START_MARKER' in $WORKFLOW; the extraction is incomplete, update this test with the refactor"
  exit 1
}
if ! grep -qF 'gh pr create' "$SNIPPET"; then
  echo "  FAIL: extracted snippet contains no 'gh pr create'; the extraction is not the PR step"
  exit 1
fi
# shellcheck disable=SC2016  # literal workflow text, must not expand
if ! grep -qF '$BODY_FILE' "$SNIPPET" || [ "$(wc -l < "$SNIPPET")" -lt 10 ]; then
  echo "  FAIL: extracted snippet looks truncated ($(wc -l < "$SNIPPET") lines)"
  exit 1
fi
ok "extracted $(wc -l < "$SNIPPET" | tr -d ' ') lines of the PR step ('$START_MARKER' .. '$END_MARKER')"

# The workflow step runs under `set -euo pipefail`; reproduce that, plus the
# BRANCH variable the step sets earlier.
RUNNER="$WORK/runner.sh"
{
  printf 'set -euo pipefail\n'
  cat "$SNIPPET"
} > "$RUNNER"

# --- gh stub -------------------------------------------------------------------
# Logs one line of args per call to $GH_LOG. `pr create` exits GH_CREATE_RC
# (default 0, with an "already exists" message on stderr when non-zero).
# `pr edit` copies its --body-file content to $GH_EDIT_BODY (the snippet
# deletes the file afterwards) and exits GH_EDIT_RC (default 0). Anything else
# is a harness surprise: exit 64 with a message.
STUB_BIN="$WORK/bin"
mkdir -p "$STUB_BIN"
# pipebuf: bounded-literal. The heredoc body is redirected straight to a
# regular file (no pipe reader involved), and its size is fixed by this file.
cat > "$STUB_BIN/gh" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
printf '%s\n' "$*" >> "${GH_LOG:?GH_LOG must be set}"
sub="${1:-} ${2:-}"
case "$sub" in
  "pr create")
    if [[ "${GH_CREATE_RC:-0}" != "0" ]]; then
      echo "a pull request for branch \"traffic/snapshot-2026-09-07\" into branch \"main\" already exists" >&2
      exit 1
    fi
    exit 0
    ;;
  "pr edit")
    body=""
    prev=""
    for a in "$@"; do
      if [[ "$prev" == "--body-file" ]]; then body="$a"; fi
      prev="$a"
    done
    if [[ -n "$body" && -f "$body" ]]; then
      cp "$body" "${GH_EDIT_BODY:?GH_EDIT_BODY must be set}"
    fi
    if [[ "${GH_EDIT_RC:-0}" != "0" ]]; then
      echo "gh: HTTP 500: stubbed pr edit failure" >&2
      exit 1
    fi
    exit 0
    ;;
  *)
    echo "gh stub: unexpected call: $*" >&2
    exit 64
    ;;
esac
EOF
chmod +x "$STUB_BIN/gh"

# --- fixture ledger --------------------------------------------------------------
# Row shape mirrors docs/traffic/snapshots.jsonl (scripts/traffic-snapshot.mjs).
# The FIRST row has different numbers than the LAST, so a body built from the
# wrong row is caught.
FIXTURE="$WORK/snapshots.jsonl"
jq -nc '{
  week: "2026-08-31", source: "github-traffic-api", generated_at: "2026-09-07T06:00:00Z",
  views:  {total: 1111, uniques: 555, days_observed: 7, days: []},
  clones: {total: 2222, uniques: 333, days_observed: 7, days: []},
  popular_paths: {window_days: 14, items: [{path: "/old/first-row-path", count: 9, uniques: 4, title: "Old"}]},
  referrers:     {window_days: 14, items: [{referrer: "old-first-row.example", count: 9, uniques: 4}]}
}' > "$FIXTURE"
jq -nc '{
  week: "2026-09-07", source: "github-traffic-api", generated_at: "2026-09-14T06:00:00Z",
  views:  {total: 7431, uniques: 3217, days_observed: 6, days: []},
  clones: {total: 98765, uniques: 4321, days_observed: 6, days: []},
  popular_paths: {window_days: 14, items: [
    {path: "/yonatangross/orchestkit/last-row-path", count: 77, uniques: 41, title: "Last"},
    {path: "/yonatangross/orchestkit/second", count: 12, uniques: 8, title: "Second"}]},
  referrers: {window_days: 14, items: [
    {referrer: "last-row.example", count: 66, uniques: 31},
    {referrer: "second.example", count: 5, uniques: 3}]}
}' >> "$FIXTURE"

# --- runner ----------------------------------------------------------------------
# run_arm <name> <create-rc> <edit-rc>   (sets ARM, RC)
run_arm() {
  local name="$1" create_rc="$2" edit_rc="$3"
  ARM="$WORK/arm-$name"
  mkdir -p "$ARM/docs/traffic"
  cp "$FIXTURE" "$ARM/docs/traffic/snapshots.jsonl"
  : > "$ARM/gh.log"
  set +e
  (
    cd "$ARM"
    env PATH="$STUB_BIN:$PATH" TMPDIR="$ARM" \
      WEEK="$WEEK_VALUE" BRANCH="$BRANCH_VALUE" \
      GH_LOG="$ARM/gh.log" GH_EDIT_BODY="$ARM/edit-body.md" \
      GH_CREATE_RC="$create_rc" GH_EDIT_RC="$edit_rc" \
      bash "$RUNNER" > "$ARM/stdout" 2> "$ARM/stderr"
  )
  RC=$?
  set -e
}

# count_calls <log> <prefix> -> number of log lines starting with prefix
count_calls() {
  awk -v p="$2" 'index($0, p) == 1 { n++ } END { print n + 0 }' "$1"
}

# --- arm: fault (create fails, edit succeeds) ----------------------------------------
echo "-- fault: gh pr create fails because the PR already exists"
run_arm fault 1 0
if [ "$RC" -eq 0 ]; then
  ok "fault: snippet exits 0 (non-fatal)"
else
  bad "fault: snippet exited $RC; stderr: $(cat "$ARM/stderr")"
fi
if [ "$(count_calls "$ARM/gh.log" "pr create ")" -eq 1 ]; then
  ok "fault: gh pr create attempted exactly once"
else
  bad "fault: expected 1 gh pr create call, log: $(cat "$ARM/gh.log")"
fi
EDIT_CALLS="$(count_calls "$ARM/gh.log" "pr edit ")"
if [ "$EDIT_CALLS" -eq 1 ]; then
  ok "fault: gh pr edit called exactly once"
else
  bad "fault: expected exactly 1 gh pr edit call, saw $EDIT_CALLS (the open PR keeps its stale body); log: $(cat "$ARM/gh.log")"
fi
EDIT_PREFIX="pr edit ${BRANCH_VALUE} --body-file ${ARM}/ork-traffic-pr."
if awk -v p="$EDIT_PREFIX" 'index($0, p) == 1 { f = 1 } END { exit !f }' "$ARM/gh.log"; then
  ok "fault: edit targets $BRANCH_VALUE with --body-file <the built body>"
else
  bad "fault: no call starting with '$EDIT_PREFIX'; log: $(cat "$ARM/gh.log")"
fi
if [ -s "$ARM/edit-body.md" ]; then
  ok "fault: the body handed to gh pr edit is non-empty"
  for needle in \
    '| views | 7431 | 3217 | 6 |' \
    '| clones | 98765 | 4321 | 6 |' \
    '- last-row.example: 66 hits, 31 uniques' \
    '/yonatangross/orchestkit/last-row-path'; do
    if grep -qF -- "$needle" "$ARM/edit-body.md"; then
      ok "fault: edit body has the last row's '$needle'"
    else
      bad "fault: edit body lacks '$needle'; body: $(cat "$ARM/edit-body.md")"
    fi
  done
  for stale in '| views | 1111 |' '| clones | 2222 |' 'old-first-row.example' 'first-row-path'; do
    if grep -qF -- "$stale" "$ARM/edit-body.md"; then
      bad "fault: edit body carries the FIRST row's '$stale'"
    else
      ok "fault: edit body does not carry the first row's '$stale'"
    fi
  done
else
  bad "fault: no body was captured from gh pr edit (edit not called or empty body file)"
fi
if grep -qF '::warning::' "$ARM/stdout"; then
  bad "fault: ::warning:: printed although the body edit succeeded; stdout: $(cat "$ARM/stdout")"
else
  ok "fault: no ::warning:: when the edit succeeds"
fi

# --- arm: control (create succeeds) ------------------------------------------------------
echo "-- control: gh pr create succeeds"
run_arm control 0 0
if [ "$RC" -eq 0 ]; then
  ok "control: snippet exits 0"
else
  bad "control: snippet exited $RC; stderr: $(cat "$ARM/stderr")"
fi
if [ "$(count_calls "$ARM/gh.log" "pr create ")" -eq 1 ]; then
  ok "control: gh pr create called exactly once"
else
  bad "control: expected 1 gh pr create call, log: $(cat "$ARM/gh.log")"
fi
if [ "$(count_calls "$ARM/gh.log" "pr edit")" -eq 0 ]; then
  ok "control: no gh pr edit call"
else
  bad "control: gh pr edit called after a successful create; log: $(cat "$ARM/gh.log")"
fi
if grep -qF "opened PR for ${BRANCH_VALUE}" "$ARM/stdout"; then
  ok "control: 'opened PR for ${BRANCH_VALUE}' printed"
else
  bad "control: 'opened PR for' line missing; stdout: $(cat "$ARM/stdout")"
fi
if grep -qF '::warning::' "$ARM/stdout"; then
  bad "control: unexpected ::warning::; stdout: $(cat "$ARM/stdout")"
else
  ok "control: no ::warning::"
fi

# --- arm: both fail --------------------------------------------------------------------------
echo "-- both: gh pr create fails and gh pr edit fails"
run_arm both 1 1
if [ "$RC" -eq 0 ]; then
  ok "both: snippet still exits 0 (never aborts the job)"
else
  bad "both: snippet exited $RC under set -e; stderr: $(cat "$ARM/stderr")"
fi
if [ "$(count_calls "$ARM/gh.log" "pr edit ")" -ge 1 ]; then
  ok "both: gh pr edit was attempted"
else
  bad "both: gh pr edit never attempted; log: $(cat "$ARM/gh.log")"
fi
if grep -qF '::warning::' "$ARM/stdout"; then
  ok "both: ::warning:: printed on stdout"
else
  bad "both: no ::warning:: line; stdout: $(cat "$ARM/stdout")"
fi
if grep -qF "opened PR for" "$ARM/stdout"; then
  bad "both: claims 'opened PR for' although create failed"
else
  ok "both: does not claim the PR was opened"
fi

echo ""
if [ "$FAIL" -gt 0 ]; then
  echo "traffic-snapshot PR body test: $FAIL failing assertion(s), $PASS passing"
  exit 1
fi
echo "traffic-snapshot PR body test: all $PASS assertions passed"
